window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4cf9d4bc9dfe4e41"]={"versions": [{"id": "FIG-4cf9d4bc9dfe4e41", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp</strong>: UML-Metamodell / Klassendiagramm-Ausschnitt aus dem AUTOSAR Basic Software Module Description Template (<code>AUTOSAR_BSWMDTemplate</code>, Release R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung</strong>: Formalisiert die statische Abhängigkeitsdeklaration (<code>BswModuleDependency</code>) eines BSW-Moduls gegenüber anderen Modulen oder Plattform-Basisdiensten. Dient BSW-Konfiguratoren und RTE/SchM-Codegeneratoren zur statischen Validierung von Aufrufbeziehungen, Ausführungskontexten, Signatur-Kompatibilitäten sowie zur automatisierten Verknüpfung von Service-Bedarfen (<code>ServiceNeeds</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleDependency</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeit eines Quellmoduls von einem spezifischen Zielmodul.</li>\n<li><code>+ targetModuleId: Int</code>: AUTOSAR BSW-Modul-ID des Zielmoduls (z. B. CanIf = 60, Com = 50).</li>\n<li><strong>Assoziationen</strong>:</li>\n<li><code>+requiredEntry</code> (<code>0..*</code>): Gerichtete Referenz auf benötigte Funktionsschnittstellen (<code>BswModuleEntry</code>) des Zielmoduls.</li>\n<li><code>+expectedCallback</code> (<code>0..*</code>): Gerichtete Referenz auf Benachrichtigungs-/Callback-Funktionen (<code>BswModuleEntry</code>), die das Quellmodul implementiert und vom Zielmodul aufgerufen werden müssen.</li>\n<li><code>+serviceItem</code> (<code>0..*</code>): Komposition (gefüllte Raute) von Anforderungen an Basisinfrastruktur-Dienste (<code>ServiceNeeds::ServiceNeeds</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntry</code></strong> (Kategorie / Stereotyp: <code>SwService</code>):</li>\n<li>Repräsentiert die formale Spezifikation einer C-Funktion / API im BSW.</li>\n<li><code>+ callType: BswCallType</code>: Aufrufsemantik (z. B. <code>Regular</code>, <code>Callback</code>, <code>Callout</code>, <code>Interrupt</code>).</li>\n<li><code>+ executionContext: BswExecutionContext</code>: Zulässiger Ausführungskontext (z. B. <code>Task</code>, <code>Isr1</code>, <code>Isr2</code>, <code>Unspecified</code>).</li>\n<li><code>+ isSynchronous: Boolean</code>: Gibt an, ob der Funktionsaufruf synchron/blockierend (<code>true</code>) oder asynchron (<code>false</code>) ist.</li>\n<li><code>+ serviceId: Int</code>: Numerische API-ID (SID) gemäß SWS-Spezifikation für Tracing und DET-Fehlerreporting.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceNeeds::ServiceNeeds</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Abstrakte Basisklasse für modulübergreifende Basissystem-Anforderungen (z. B. NvM-Blockspeicherbedarf, Dem-Fehlerereignisse, EcuM-State-Requests, ComM-Kanäle).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statischen Invarianten zur Absicherung der dynamischen Interaktionspfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Synchrone Dienstabfrage</strong>: Quellmodul ruft <code>requiredEntry</code> mit <code>isSynchronous = true</code> auf. Die Ausführung verbleibt vollständig im selben <code>executionContext</code> des Aufrufers.</li>\n<li><strong>Asynchrone Interaktion & Callback-Kopplung</strong>: Quellmodul stößt eine Operation über einen asynchronen <code>requiredEntry</code> (<code>isSynchronous = false</code>) an. Das Zielmodul signalisiert den Abschluss oder Zwischenzustände über den korrespondierenden <code>expectedCallback</code>.</li>\n<li><strong>Kontextprüfung</strong>: APIs mit abweichendem <code>executionContext</code> (z. B. Aufruf einer Task-gebundenen API aus einem ISR2-Kontext) werden werkzeugseitig als ungültige Übergänge identifiziert.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Modulentwickler</strong>:</li>\n<li>Jede externe Modulabhängigkeit muss in der BSWMD (<code>.arxml</code>) des Moduls lückenlos hinterlegt sein.</li>\n<li><code>serviceId</code> und <code>targetModuleId</code> müssen exakt mit den normativen IDs der jeweiligen SWS übereinstimmen; sie fließen direkt in Parameter von <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> ein.</li>\n<li>Callbacks (<code>expectedCallback</code>) müssen in Signatur und Ausführungskontext gegen die Bereitstellung des Zielmoduls validiert werden.</li>\n<li><strong>Integratoren & Toolchain-Generatoren</strong>:</li>\n<li>Konfiguratoren nutzen <code>ServiceNeeds</code>, um abhängige Basis-Stacks (NvM, Dem, EcuM) automatisch vorzuparametrieren (z. B. automatische Allokation von NVRAM-Blöcken oder Diagnose-Event-IDs).</li>\n<li>Inkonsistenzen zwischen deklariertem <code>executionContext</code> und tatsächlicher Task-Konfiguration (SchM/OS) erzeugen Integrationsfehler vor dem Build.</li>\n</ul>"}, {"id": "FIG-80ba5b3d87b3d37e", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp</strong>: UML-Metamodell / Klassendiagramm-Ausschnitt aus dem AUTOSAR Basic Software Module Description Template (<code>AUTOSAR_BSWMDTemplate</code>, Release R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung</strong>: Formalisiert die statische Abhängigkeitsdeklaration (<code>BswModuleDependency</code>) eines BSW-Moduls gegenüber anderen Modulen oder Plattform-Basisdiensten. Dient BSW-Konfiguratoren und RTE/SchM-Codegeneratoren zur statischen Validierung von Aufrufbeziehungen, Ausführungskontexten, Signatur-Kompatibilitäten sowie zur automatisierten Verknüpfung von Service-Bedarfen (<code>ServiceNeeds</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleDependency</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeit eines Quellmoduls von einem spezifischen Zielmodul.</li>\n<li><code>+ targetModuleId: Int</code>: AUTOSAR BSW-Modul-ID des Zielmoduls (z. B. CanIf = 60, Com = 50).</li>\n<li><strong>Assoziationen</strong>:</li>\n<li><code>+requiredEntry</code> (<code>0..*</code>): Gerichtete Referenz auf benötigte Funktionsschnittstellen (<code>BswModuleEntry</code>) des Zielmoduls.</li>\n<li><code>+expectedCallback</code> (<code>0..*</code>): Gerichtete Referenz auf Benachrichtigungs-/Callback-Funktionen (<code>BswModuleEntry</code>), die das Quellmodul implementiert und vom Zielmodul aufgerufen werden müssen.</li>\n<li><code>+serviceItem</code> (<code>0..*</code>): Komposition (gefüllte Raute) von Anforderungen an Basisinfrastruktur-Dienste (<code>ServiceNeeds::ServiceNeeds</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntry</code></strong> (Kategorie / Stereotyp: <code>SwService</code>):</li>\n<li>Repräsentiert die formale Spezifikation einer C-Funktion / API im BSW.</li>\n<li><code>+ callType: BswCallType</code>: Aufrufsemantik (z. B. <code>Regular</code>, <code>Callback</code>, <code>Callout</code>, <code>Interrupt</code>).</li>\n<li><code>+ executionContext: BswExecutionContext</code>: Zulässiger Ausführungskontext (z. B. <code>Task</code>, <code>Isr1</code>, <code>Isr2</code>, <code>Unspecified</code>).</li>\n<li><code>+ isSynchronous: Boolean</code>: Gibt an, ob der Funktionsaufruf synchron/blockierend (<code>true</code>) oder asynchron (<code>false</code>) ist.</li>\n<li><code>+ serviceId: Int</code>: Numerische API-ID (SID) gemäß SWS-Spezifikation für Tracing und DET-Fehlerreporting.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceNeeds::ServiceNeeds</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Abstrakte Basisklasse für modulübergreifende Basissystem-Anforderungen (z. B. NvM-Blockspeicherbedarf, Dem-Fehlerereignisse, EcuM-State-Requests, ComM-Kanäle).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statischen Invarianten zur Absicherung der dynamischen Interaktionspfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Synchrone Dienstabfrage</strong>: Quellmodul ruft <code>requiredEntry</code> mit <code>isSynchronous = true</code> auf. Die Ausführung verbleibt vollständig im selben <code>executionContext</code> des Aufrufers.</li>\n<li><strong>Asynchrone Interaktion & Callback-Kopplung</strong>: Quellmodul stößt eine Operation über einen asynchronen <code>requiredEntry</code> (<code>isSynchronous = false</code>) an. Das Zielmodul signalisiert den Abschluss oder Zwischenzustände über den korrespondierenden <code>expectedCallback</code>.</li>\n<li><strong>Kontextprüfung</strong>: APIs mit abweichendem <code>executionContext</code> (z. B. Aufruf einer Task-gebundenen API aus einem ISR2-Kontext) werden werkzeugseitig als ungültige Übergänge identifiziert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Modulentwickler</strong>:</li>\n<li>Jede externe Modulabhängigkeit muss in der BSWMD (<code>.arxml</code>) des Moduls lückenlos hinterlegt sein.</li>\n<li><code>serviceId</code> und <code>targetModuleId</code> müssen exakt mit den normativen IDs der jeweiligen SWS übereinstimmen; sie fließen direkt in Parameter von <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> ein.</li>\n<li>Callbacks (<code>expectedCallback</code>) müssen in Signatur und Ausführungskontext gegen die Bereitstellung des Zielmoduls validiert werden.</li>\n<li><strong>Integratoren & Toolchain-Generatoren</strong>:</li>\n<li>Konfiguratoren nutzen <code>ServiceNeeds</code>, um abhängige Basis-Stacks (NvM, Dem, EcuM) automatisch vorzuparametrieren (z. B. automatische Allokation von NVRAM-Blöcken oder Diagnose-Event-IDs).</li>\n<li>Inkonsistenzen zwischen deklariertem <code>executionContext</code> und tatsächlicher Task-Konfiguration (SchM/OS) erzeugen Integrationsfehler vor dem Build.</li>\n</ul>"}, {"id": "FIG-e84672f1da4f991f", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Diagrammtyp</strong>: UML-Metamodell / Klassendiagramm-Ausschnitt aus dem AUTOSAR Basic Software Module Description Template (<code>AUTOSAR_BSWMDTemplate</code>, Release R3.0.7).</li>\n<li><strong>Technischer Zweck & Einordnung</strong>: Formalisiert die statische Abhängigkeitsdeklaration (<code>BswModuleDependency</code>) eines BSW-Moduls gegenüber anderen Modulen oder Plattform-Basisdiensten. Dient BSW-Konfiguratoren und RTE/SchM-Codegeneratoren zur statischen Validierung von Aufrufbeziehungen, Ausführungskontexten, Signatur-Kompatibilitäten sowie zur automatisierten Verknüpfung von Service-Bedarfen (<code>ServiceNeeds</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleDependency</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Kapselt die Abhängigkeit eines Quellmoduls von einem spezifischen Zielmodul.</li>\n<li><code>+ targetModuleId :Integer</code>: AUTOSAR BSW-Modul-ID des Zielmoduls (z. B. CanIf = 60, Com = 50).</li>\n<li><strong>Assoziationen</strong>:</li>\n<li><code>+requiredEntry</code> (<code>0..*</code>): Gerichtete Referenz auf benötigte Funktionsschnittstellen (<code>BswModuleEntry</code>) des Zielmoduls.</li>\n<li><code>+expectedCallback</code> (<code>0..*</code>): Gerichtete Referenz auf Benachrichtigungs-/Callback-Funktionen (<code>BswModuleEntry</code>), die das Quellmodul implementiert und vom Zielmodul aufgerufen werden müssen.</li>\n<li><code>+serviceItem</code> (<code>0..*</code>): Komposition (gefüllte Raute) von Anforderungen an Basisinfrastruktur-Dienste (<code>ServiceNeeds::ServiceNeeds</code>).</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>BswModuleEntry</code></strong> (Kategorie / Stereotyp: <code>SwService</code>):</li>\n<li>Repräsentiert die formale Spezifikation einer C-Funktion / API im BSW.</li>\n<li><code>+ callType :BswCallType</code>: Aufrufsemantik (z. B. <code>Regular</code>, <code>Callback</code>, <code>Callout</code>, <code>Interrupt</code>).</li>\n<li><code>+ executionContext :BswExecutionContext</code>: Zulässiger Ausführungskontext (z. B. <code>Task</code>, <code>Isr1</code>, <code>Isr2</code>, <code>Unspecified</code>).</li>\n<li><code>+ isSynchronous :Boolean</code>: Gibt an, ob der Funktionsaufruf synchron/blockierend (<code>true</code>) oder asynchron (<code>false</code>) ist.</li>\n<li><code>+ serviceId :Integer</code>: Numerische API-ID (SID) gemäß SWS-Spezifikation für Tracing und DET-Fehlerreporting.</li>\n</ul>\n<ul class=\"fig-list\">\n<li><strong><code>ServiceNeeds::ServiceNeeds</code></strong> (Generalisierung: <code>Identifiable</code>):</li>\n<li>Abstrakte Basisklasse für modulübergreifende Basissystem-Anforderungen (z. B. NvM-Blockspeicherbedarf, Dem-Fehlerereignisse, EcuM-State-Requests, ComM-Kanäle).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Metamodell definiert die statischen Invarianten zur Absicherung der dynamischen Interaktionspfade:</p>\n<ul class=\"fig-list\">\n<li><strong>Synchrone Dienstabfrage</strong>: Quellmodul ruft <code>requiredEntry</code> mit <code>isSynchronous = true</code> auf. Die Ausführung verbleibt vollständig im selben <code>executionContext</code> des Aufrufers.</li>\n<li><strong>Asynchrone Interaktion & Callback-Kopplung</strong>: Quellmodul stößt eine Operation über einen asynchronen <code>requiredEntry</code> (<code>isSynchronous = false</code>) an. Das Zielmodul signalisiert den Abschluss oder Zwischenzustände über den korrespondierenden <code>expectedCallback</code>.</li>\n<li><strong>Kontextprüfung</strong>: APIs mit abweichendem <code>executionContext</code> (z. B. Aufruf einer Task-gebundenen API aus einem ISR2-Kontext) werden werkzeugseitig als ungültige Übergänge identifiziert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>BSW-Modulentwickler</strong>:</li>\n<li>Jede externe Modulabhängigkeit muss in der BSWMD (<code>.arxml</code>) des Moduls lückenlos hinterlegt sein.</li>\n<li><code>serviceId</code> und <code>targetModuleId</code> müssen exakt mit den normativen IDs der jeweiligen SWS übereinstimmen; sie fließen direkt in Parameter von <code>Det_ReportError(ModuleId, InstanceId, ApiId, ErrorId)</code> ein.</li>\n<li>Callbacks (<code>expectedCallback</code>) müssen in Signatur und Ausführungskontext gegen die Bereitstellung des Zielmoduls validiert werden.</li>\n<li><strong>Integratoren & Toolchain-Generatoren</strong>:</li>\n<li>Konfiguratoren nutzen <code>ServiceNeeds</code>, um abhängige Basis-Stacks (NvM, Dem, EcuM) automatisch vorzuparametrieren (z. B. automatische Allokation von NVRAM-Blöcken oder Diagnose-Event-IDs).</li>\n<li>Inkonsistenzen zwischen deklariertem <code>executionContext</code> und tatsächlicher Task-Konfiguration (SchM/OS) erzeugen Integrationsfehler vor dem Build.</li>\n</ul>"}], "trans": [{"from": "FIG-4cf9d4bc9dfe4e41", "to": "FIG-80ba5b3d87b3d37e", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-80ba5b3d87b3d37e", "to": "FIG-e84672f1da4f991f", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>BswModuleDependency</code>: Datentyp des Attributs <code>targetModuleId</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>BswModuleEntry</code>: Datentyp des Attributs <code>serviceId</code> von <code>Int</code> zu <code>Integer</code> geändert.</li>\n<li><code>BswModuleEntry</code>: Formatierung der Attribut-Typspezifikatoren (<code>callType</code>, <code>executionContext</code>, <code>isSynchronous</code>, <code>serviceId</code>) durch vorangestelltes Leerzeichen vor dem Doppelpunkt vereinheitlicht.</li>\n</ul>"}]};
